class Solution {
  public int minIncrease(int n, int[][] edges, int[] cost) {
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int[] order = new int[n], par = new int[n];
    par[0] = -1;
    int head = 0, tail = 0;
    order[tail++] = 0;
    while (head < tail) {
      int u = order[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] != par[u]) {
          par[to[p]] = u;
          order[tail++] = to[p];
        }
      }
    }
    long[] best = new long[n];
    int ans = 0;
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      long mx = 0;
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] == par[u]) continue;
        mx = Math.max(mx, best[to[p]]);
      }
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] != par[u] && best[to[p]] < mx) ans++;
      }
      best[u] = cost[u] + mx;
    }
    return ans;
  }
}
